  SELECT 'acc_print_F_OuvertureFeminin', '401787', 50
  UNION ALL
  SELECT 'acc_print_U_Chucky', '401788', 50
  UNION ALL
  SELECT 'acc_print_U_rareselena', '401789', 50
  UNION ALL
  SELECT 'acc_print_U_axeidragonyearcolor', '401790', 50
  ) n
 WHERE NOT EXISTS (SELECT 1 FROM `catalog_clothing` c
                    WHERE c.`clothing_name` = n.`clothing_name`
                       OR FIND_IN_SET(SUBSTRING_INDEX(n.`clothing_parts`, ',', 1), c.`clothing_parts`) > 0);
